#include <vector>
using namespace std;

int kSumPairsBrute(vector<int>& a, int k) {
    int n = (int)a.size(), pairs = 0;
    vector<bool> used(n, false);
    for (int i = 0; i < n; ++i) {
        if (used[i]) continue;
        for (int j = i + 1; j < n; ++j)
            if (!used[j] && (long long)a[i] + a[j] == k) {
                used[i] = used[j] = true;
                ++pairs;
                break;
            }
    }
    return pairs;
}
