def min_subarray_brute(a, p):
    n = len(a)
    total = sum(a) % p
    if total == 0:
        return 0
    best = n + 1
    for i in range(n):
        run = 0
        for j in range(i, n):
            run = (run + a[j]) % p
            if run == total and j - i + 1 < n:   # proper window only
                best = min(best, j - i + 1)
    return best if best <= n else -1
```
