#include <vector>
using namespace std;

int minSubarrayBrute(vector<int>& a, int p) {
    int n = (int)a.size();
    long long total = 0;
    for (int x : a) total = (total + x) % p;
    if (total == 0) return 0;
    int best = n + 1;
    for (int i = 0; i < n; ++i) {
        long long run = 0;
        for (int j = i; j < n; ++j) {
            run = (run + a[j]) % p;
            if (run == total && j - i + 1 < n) best = min(best, j - i + 1);
        }
    }
    return best <= n ? best : -1;
}
